/**
 *  An attestation that an actor performed an action — the audit row every
 *  auto-answer, state flip, and side effect leaves behind. The
 *  liveness-producer flip rule's receipt uses `subject_type = "attempt"`,
 *  `from`/`to` as the flip edge, and `observed_basis` naming the liveness
 *  evidence.
 */
export type Receipt = Receipt_Serialize | Receipt_Deserialize;

export type ReceiptId = string;

/**
 *  An attestation that an actor performed an action — the audit row every
 *  auto-answer, state flip, and side effect leaves behind. The
 *  liveness-producer flip rule's receipt uses `subject_type = "attempt"`,
 *  `from`/`to` as the flip edge, and `observed_basis` naming the liveness
 *  evidence.
 */
export type Receipt_Deserialize = {
	id: ReceiptId,
	actor: Actor_Deserialize,
	/**  OPEN action attested (e.g. `state_flip`, `auto_answer`, `deploy`). */
	action: string,
	subject_type: string,
	subject_id: string,
	from?: string | null,
	to?: string | null,
	observed_basis?: string | null,
	ts: Timestamp,
};

/**
 *  An attestation that an actor performed an action — the audit row every
 *  auto-answer, state flip, and side effect leaves behind. The
 *  liveness-producer flip rule's receipt uses `subject_type = "attempt"`,
 *  `from`/`to` as the flip edge, and `observed_basis` naming the liveness
 *  evidence.
 */
export type Receipt_Serialize = {
	id: ReceiptId,
	actor: Actor_Serialize,
	/**  OPEN action attested (e.g. `state_flip`, `auto_answer`, `deploy`). */
	action: string,
	subject_type: string,
	subject_id: string,
	from?: string | null,
	to?: string | null,
	observed_basis?: string | null,
	ts: Timestamp,
};

/**
 *  The v2 Context write grammar, in full.
 *
 *  One shape, one field. Recording a fact is the ONLY Context write, because
 *  Context may compile, verify, attest, project, explain, compare and suggest —
 *  and may not independently authorize work or write execution truth outside
 *  kernel commands (ADR-0032). A grammar with a second verb would be a second
 *  write authority wearing a smaller name.
 *
 *  **There is no actor field here and there must never be one.** See CTX-12 in
 *  the module docs; the omission is asserted by test, not left to review.
 */
