/**  The exact adapter-rendered material and tool schemas released to an engine. */
export type ReleaseSupplement = {
	id: string,
	manifest_id: string,
	rendered_digest: string,
	tool_schema_digest: string,
	rendered_bytes: string,
	tool_schema_count: number,
	evidence_ids: EvidenceId[],
	released_at: Timestamp,
};

/**
 *  Correlates one wire request with its response, event batch, or stream
 *  close. Client-minted and echoed back unchanged.
 */
export type RequestId = string;

/**  The one immutable compiler output for a spawn attempt. */
export type ResolvedManifest = ResolvedManifest_Serialize | ResolvedManifest_Deserialize;

/**  The one immutable compiler output for a spawn attempt. */
export type ResolvedManifest_Deserialize = {
	id: string,
	attempt_id: AttemptId,
	manifest_digest: string,
	route_digest: string,
	authority_digest: string,
	source_count: number,
	source_bytes: string,
	participations: Participation_Deserialize[],
	evidence_ids: EvidenceId[],
	resolved_at: Timestamp,
};

/**  The one immutable compiler output for a spawn attempt. */
export type ResolvedManifest_Serialize = {
	id: string,
	attempt_id: AttemptId,
	manifest_digest: string,
	route_digest: string,
	authority_digest: string,
	source_count: number,
	source_bytes: string,
	participations: Participation_Serialize[],
	evidence_ids: EvidenceId[],
	resolved_at: Timestamp,
};

